('61cac813-a98a-4e72-a4e8-bc914213a0a0','MA','a8888888-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Atlas Cultural Tours SARL','Atlas Cultural Tours','tour',3,'verified',ARRAY['en','fr','de'],'Mid-size cultural tour operator with air-conditioned minibuses and university-trained historians. We cover major landmarks with comfortable logistics.',4.7,91.8,442,4.7,'active'),
('535864a4-4882-43a9-a61e-d8cd3060d6f5','MA','a8888888-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Royal Concierge Chefchaouen SARL','Royal Concierge Chefchaouen','tour',4,'verified',ARRAY['en','fr','es','it'],'Private luxury touring service with Mercedes vans, art-historian guides, and exclusive access to private palaces and collections not open to the public.',1.8,90.4,126,4.3,'active'),
('0898754c-2ab3-404f-a786-88e66c879da8','MA','a8888888-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Local Eyes Chefchaouen SARL','Local Eyes Chefchaouen','guided_experience',1,'verified',ARRAY['en','fr','ary-Latn'],'A collective of young local guides who show you the real city — hidden cafes, street art, and neighborhoods the guidebooks miss. Pay-what-you-want ethos.',8.7,89.3,431,4.8,'active'),
('2b23c694-95ac-4dff-8965-8ac2106c237b','MA','a8888888-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Insider Morocco SARL','Insider Morocco','guided_experience',3,'verified',ARRAY['en','fr','ar'],'Boutique guiding company pairing you with a dedicated guide for a personalized half-day or full-day experience. We adapt the route to your interests on the fly.',9.4,88.1,196,3.9,'active'),
('40bcad3b-dc73-4809-9c39-29576e56a447','MA','a8888888-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Kasbah Storytellers SARL','Kasbah Storytellers','guided_experience',2,'verified',ARRAY['en','fr','ary-Latn'],'Cultural preservation association. Our guides are retired teachers and historians who share oral traditions, folklore, and stories passed down for generations.',5.3,92.2,146,4.5,'active'),
('8681a7a9-f94b-4630-b570-f21d8a87b65d','MA','a8888888-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Dar Chefchaouen Cooking School SARL','Dar Chefchaouen Cooking School','workshop',2,'verified',ARRAY['en','fr','ary-Latn'],'A traditional riad kitchen where a local family teaches you to prepare tagine, couscous, and pastries from scratch. Small classes, maximum 6 people.',10.6,90.3,52,4.3,'active'),
('967f9843-e362-45bb-ac64-48b0df914bc4','MA','a8888888-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Maison des Artisans SARL','Maison des Artisans','workshop',2,'verified',ARRAY['en','fr','ar'],'A cooperative workshop space where master artisans — potters, leatherworkers, zellige cutters — teach their craft in 2-hour hands-on sessions. Materials included.',3.7,97.9,293,4.1,'active'),
('856c9721-a860-45c9-9dcd-18986672f57d','MA','a8888888-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Atelier Lumière SARL','Atelier Lumière','workshop',4,'verified',ARRAY['en','fr','es'],'A luxury creative studio offering private masterclasses with acclaimed Moroccan artists. Photography, calligraphy, and perfume-making in a beautifully restored medina house.',1.8,96.2,20,4.1,'active'),
('55602c64-1384-4588-82d6-035f3a3887bf','MA','a8888888-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Riad Chefchaouen Budget SARL','Riad Chefchaouen Budget','stay',1,'verified',ARRAY['en','fr'],'A clean, friendly guesthouse in the heart of the medina. Shared bathrooms, rooftop terrace, and free mint tea. Perfect for backpackers and solo travelers.',2.8,94.1,338,3.8,'active'),
('4165ba36-f604-4e98-a961-796b06947084','MA','a8888888-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Dar Chefchaouen Boutique SARL','Dar Chefchaouen Boutique','stay',3,'verified',ARRAY['en','fr','es'],'A beautifully restored 19th-century riad with 8 rooms, each uniquely decorated with antiques and local textiles. Plunge pool, hammam, and breakfast on the rooftop.',8.6,89.5,354,4.2,'active'),
('692d55a9-7439-4e28-b6d3-8c69b8e0b71f','MA','a8888888-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Palais Chefchaouen Royal SARL','Palais Chefchaouen Royal','stay',4,'verified',ARRAY['en','fr','it','de'],'A former palace converted into an all-suite luxury hotel. Private butlers, Michelin-trained chef, spa, and curated excursions. The finest address in the city.',4.4,92.3,397,4.8,'active'),
('7fa034ff-bb66-4549-8985-f73403d7ce9f','MA','a8888888-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Street Food Chefchaouen Tours SARL','Street Food Chefchaouen Tours','meal',1,'verified',ARRAY['en','fr','ary-Latn'],'We take you through the best food stalls and hidden corners of the medina. 6+ tastings, from bissara to snail soup. Come hungry!',5.9,93.9,161,3.8,'active'),
('c68ecf23-2abc-451b-b544-3a776d885a08','MA','a8888888-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Table Chefchaouen Family Kitchen SARL','Table Chefchaouen Family Kitchen','meal',2,'verified',ARRAY['en','fr','ary-Latn'],'A Moroccan family welcomes you into their home for a traditional 3-course dinner. Couscous on Fridays, tagine every day. Recipes passed down four generations.',2.8,91.9,101,4.7,'active'),
('d4c576e9-21cd-4e0e-b1cb-4f81ba2531a6','MA','a8888888-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Le Salon Chefchaouen SARL','Le Salon Chefchaouen','meal',4,'verified',ARRAY['en','fr'],'Fine dining in an elegant riad setting. Modern Moroccan cuisine by a chef trained in Paris and Marrakech. Wine pairing available. Reservation required.',4.2,98.4,402,4.9,'active'),
('df598ce3-c630-4411-9c30-99cc10492319','MA','a8888888-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Chefchaouen Adventure Club SARL','Chefchaouen Adventure Club','activity',2,'verified',ARRAY['en','fr','ar'],'A local outdoor club offering hiking, cycling, and climbing for all levels. Certified guides, quality equipment, and a passion for sharing Morocco''s natural beauty.',7.5,89.5,237,4.1,'active'),
